import {FAMILY_RECORD_STATUSES} from './family-ledger.js';
import {payoutProjection} from './financial.js';
import {RECORD_TYPES,DOCUMENT_STATUSES,compareActualPayment,recordImportFields} from './case-records.js';
import {calcEscape as esc,calcMoney} from './calculator-view.js';
import {calcDownload} from './calculator-tools.js';
export function createRecordsView({store,calculatorStore,sheetContent,notify,onChange,onUseRecord}){
 const text=(key,label,v='',type='text')=>`<label class="calc-field"><span>${label}</span><input name="${key}" type="${type}" value="${esc(v??'')}" ${type==='number'?'min="0" step=".01"':''} maxlength="200"></label>`;
 const select=(key,label,items,v='')=>`<label class="calc-field"><span>${label}</span><select name="${key}"><option value="">Nie przypisano / do ustalenia</option>${items.map(([id,name])=>`<option value="${esc(id)}" ${id===v?'selected':''}>${esc(name)}</option>`).join('')}</select></label>`;
 function open(kind='decisions',editing){const snapshot=store.snapshot();if(!snapshot.available){sheetContent('Moje sprawy','<p>'+esc(snapshot.error)+'</p>');return;}const v=editing||{},items=snapshot.records[kind],people=snapshot.records.persons.map(p=>[p.id,p.name]),children=snapshot.records.children.map(p=>[p.id,p.name]),cases=calculatorStore.snapshot().cases.map(p=>[p.id,p.title]);let fields=text('name','Nazwa / oznaczenie wpisu',v.name);
 if(kind==='children')fields+=text('birthDate','Data urodzenia',v.birthDate,'date');
 if(!['persons','children'].includes(kind))fields+=select('personId','Osoba, której dotyczy',people,v.personId)+select('childId','Dziecko, którego dotyczy',children,v.childId)+select('caseId','Powiązany zapis kalkulatora',cases,v.caseId);
 if(['relations','familyEvents','medicalEvents'].includes(kind))fields+=text(kind==='relations'?'relation':'eventType',kind==='relations'?'Relacja / status prawny':'Rodzaj zdarzenia',v.relation||v.eventType);
 if(kind==='insurance')fields+=select('occupation','Tytuł',[['employee','Umowa o pracę'],['contract','Zlecenie'],['business','Działalność'],['krus','KRUS']],v.occupation)+select('coverage','Chorobowe',[['compulsory','Obowiązkowe'],['voluntary','Dobrowolne'],['none','Brak'],['unknown','Do ustalenia']],v.coverage);
 if(!['persons','children'].includes(kind))fields+=text('start','Okres od',v.start,'date')+text('end','Okres do',v.end,'date');
 if(['decisions','applications','payments','familyEvents','medicalEvents'].includes(kind))fields+=text('date',kind==='payments'?'Data rzeczywistej wypłaty':kind==='decisions'?'Data wydania decyzji':'Data zdarzenia / sporządzenia',v.date,'date');
 if(['decisions','applications'].includes(kind))fields+=text('submitted','Data złożenia wniosku',v.submitted,'date')+text('delivered','Data doręczenia decyzji',v.delivered,'date')+text('finalDate','Data ostateczności / prawomocności, jeśli dotyczy',v.finalDate,'date')+text('reference','Własne oznaczenie dokumentu (bez PESEL)',v.reference);
 if(['decisions','payments'].includes(kind))fields+=text('grossAmount','Kwota brutto z dokumentu (jeśli znana)',v.grossAmount,'number');
 if(kind==='payments')fields+=text('netAmount','Rzeczywisty przelew netto',v.netAmount,'number')+text('taxAdvance','Zaliczka PIT z rozliczenia',v.taxAdvance,'number')+text('healthDeduction','Potrącona składka zdrowotna, jeśli dotyczy',v.healthDeduction,'number')+text('otherDeductions','Inne potrącenia',v.otherDeductions,'number');
 if(kind==='employment')fields+=text('salary','Miesięczne wynagrodzenie brutto',v.salary,'number');
 if(kind==='periods')fields+=select('focus','Zakres',[['family','Rodzicielstwo'],['care','Opiekuńczy'],['sickness','Chorobowe'],['rehab','Rehabilitacyjne'],['prebirth','Przed porodem']],v.focus)+select('benefitKind','Rodzaj okresu',[['maternity','Macierzyński / na jego warunkach'],['parental','Rodzicielski'],['paternity','Ojcowski'],['care','Opiekuńczy'],['other','Inny']],v.benefitKind)+select('careType','Przy opiekuńczym',[['sick-child','Chore dziecko do 14 lat'],['sick-child-older','Starsze chore dziecko'],['disabled-child','Szczególny limit niepełnosprawności'],['adult','Chory członek rodziny'],['extra-newborn','Dodatkowa opieka pierwszych 8 tygodni']],v.careType)+select('status','Stan okresu',[['planned','Planowany'],['requested','Złożono wniosek'],['approved','Zatwierdzony według dokumentu'],['used','Wykorzystany'],['paid','Wypłacony']],v.status);
 if(kind==='periods')fields+=text('work','Praca podczas rodzicielskiego (część pełnego etatu, 0–0,5)',v.work,'number')+text('rate','Stawka zasiłku (%) z dokumentu, jeśli znana',v.rate,'number');
 if(kind==='documents')fields+=text('documentCode','Kod / nazwa dokumentu',v.documentCode)+select('status','Stan przygotowania',Object.entries(DOCUMENT_STATUSES),v.status||'missing');
 fields+=text('retentionUntil','Przypomnij o usunięciu / przeglądzie danych po (opcjonalnie)',v.retentionUntil,'date');
 sheetContent('Moje sprawy — '+RECORD_TYPES[kind],`<p>Wpisujesz informacje z własnych dokumentów. Nie są automatycznie potwierdzane przez urząd. Decyzje i wypłaty zapisujemy oddzielnie od symulacji.</p><nav class="records-tabs">${Object.entries(RECORD_TYPES).map(([id,label])=>`<button class="text-button" type="button" data-record-kind="${id}" aria-pressed="${kind===id}">${label}</button>`).join('')}</nav><form id="records-form"><div class="calc-fields">${fields}</div><button class="primary" type="submit">${editing?'Zapisz poprawkę z zachowaniem poprzedniej wersji':'Dodaj wpis'}</button><p id="records-error" class="calc-error" hidden></p></form><section><h3>Zapisane wpisy</h3>${items.map(r=>`<article class="case-card"><h4>${esc(r.name||r.documentCode)}</h4><p>${esc(r.start||r.date||r.birthDate||'')}${r.end?' — '+esc(r.end):''}</p>${r.status?'<p>'+esc(DOCUMENT_STATUSES[r.status]||FAMILY_RECORD_STATUSES[r.status]||r.status)+'</p>':''}${r.retentionUntil?'<p>Przegląd danych po: '+esc(r.retentionUntil)+'</p>':''}<button class="text-button" data-record-edit="${esc(r.id)}">Popraw</button><button class="text-button" data-record-delete="${esc(r.id)}">Usuń</button>${['insurance','employment','children'].includes(kind)?'<button class="secondary" data-record-use="'+esc(r.id)+'">Użyj tych danych w kalkulatorze</button>':''}${kind==='payments'&&r.caseId?`<button class="secondary" data-record-compare="${esc(r.id)}">Dlaczego wypłata różni się od kalkulatora?</button>`:''}</article>`).join('')||'<p>Nie dodano jeszcze wpisów.</p>'}</section><button class="secondary" id="records-export">Pobierz kopię własnego rejestru</button>`);
 document.querySelectorAll('[data-record-kind]').forEach(b=>b.onclick=()=>open(b.dataset.recordKind));
 document.querySelector('#records-form').onsubmit=e=>{e.preventDefault();try{store.save(kind,{...Object.fromEntries(new FormData(e.target)),id:v.id});onChange?.();open(kind);notify('Zapisano wpis. Powiązane wyliczenia wymagają ponownego sprawdzenia.');}catch(error){const el=document.querySelector('#records-error');el.hidden=false;el.textContent=error.message;}};
 document.querySelectorAll('[data-record-edit]').forEach(b=>b.onclick=()=>open(kind,items.find(r=>r.id===b.dataset.recordEdit)));
 document.querySelectorAll('[data-record-delete]').forEach(b=>b.onclick=()=>{sheetContent('Usunąć ten wpis?','<p>To usunie wpis z Twojego rejestru. Nie jest to wycofanie dokumentu z urzędu.</p><button class="primary" id="record-delete-confirm">Usuń wpis</button><button class="secondary" id="record-delete-cancel">Zostaw</button>');document.querySelector('#record-delete-cancel').onclick=()=>document.querySelector('#sheet').close();document.querySelector('#record-delete-confirm').onclick=()=>{store.remove(kind,b.dataset.recordDelete);onChange?.();open(kind);};});
 document.querySelectorAll('[data-record-compare]').forEach(b=>b.onclick=()=>{const payment=items.find(r=>r.id===b.dataset.recordCompare),calculation=calculatorStore.snapshot().cases.find(c=>c.id===payment.caseId);if(!calculation){notify('Powiązany scenariusz nie jest dostępny.');return;}const comparison=compareActualPayment(payment,calculation.result);let projection;try{projection=payoutProjection(payment.grossAmount,payment);}catch(e){projection={net:null,reason:e.message};}sheetContent('Porównanie rzeczywistej wypłaty',`<p>Oczekiwane brutto za wskazany okres: ${calcMoney(comparison.expectedGross)}.</p><p>Brutto z dokumentu: ${calcMoney(comparison.actualGross)}. Rzeczywiste netto: ${calcMoney(comparison.actualNet)}.</p><p>Netto odtworzone z podanych potrąceń: ${calcMoney(projection.net)}. ${esc(projection.reason||projection.description||'')}</p><p>Różnica porównywalnych kwot brutto: ${calcMoney(comparison.difference)}.</p><ul>${comparison.messages.map(s=>'<li>'+esc(s)+'</li>').join('')}</ul>`);});
 document.querySelectorAll('[data-record-use]').forEach(b=>b.onclick=()=>{try{const patch=recordImportFields(snapshot,kind,b.dataset.recordUse);sheetContent('Dane z mojego rejestru','<p>Wprowadzimy tylko wskazane wartości. Data zatrudnienia nie jest datą objęcia chorobowym, a wynagrodzenie nie jest ustaloną podstawą zasiłku.</p><ul>'+patch.importFields.map(f=>'<li>'+esc(({occupation:'Tytuł',coverage:'Chorobowe',insuranceFrom:'Ubezpieczenie od',insuranceTo:'Ubezpieczenie do',salary:'Wynagrodzenie brutto',childBirthDate:'Urodzenie dziecka'})[f.field])+': '+esc(f.value)+'</li>').join('')+'</ul>'+select('record-parent','Osoba w kalkulatorze', [['0','Osoba 1'],['1','Osoba 2']])+(kind==='children'?'':select('record-title','Tytuł tej osoby', [['0','Główny tytuł'],['1','Dodatkowy tytuł 1'],['2','Dodatkowy tytuł 2'],['3','Dodatkowy tytuł 3']]))+'<button class="primary" id="record-use-confirm">Wprowadź do formularza</button><p id="record-use-error" role="alert"></p>');document.querySelector('#record-use-confirm').onclick=()=>{const parent=document.querySelector('[name=record-parent]').value,title=kind==='children'?'0':document.querySelector('[name=record-title]').value;if(parent===''||title===''){document.querySelector('#record-use-error').textContent='Wybierz osobę i właściwy tytuł. Dotychczasowy wynik nie został zmieniony.';return;}onUseRecord?.({...patch,parent:Number(parent),title:Number(title)});};}catch(e){notify(e.message);}});
 document.querySelector('#records-export').onclick=()=>calcDownload('moje-sprawy.json',store.export(),'application/json');
 }
 return {open};
}
